    prices.iter().sum()
}

pub fn discount(price: u32, percent: u32) -> u32 {
    price - price * percent / 100
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn totals_prices() {
        let total = total(&[1, 2]);
        assert_eq!(total, 3);
        assert_eq!(super::total(&[]), 0);
    }

    #[test]
    fn applies_a_discount() {
        assert_eq!(discount(100, 10), 90);
    }
}

